/**
 * Shared mutable state for the plugin-runner permission-staging test.
 * Stub modules generated by registerHooks import this file by file URL so the
 * test and the runner observe the same FakeTransport instance.
 */
export const state = {
  transport: null,
  notifications: [],
  setCalls: [],
}

export class FakeTransport {
  constructor() {
    state.transport = this
  }
  onRequest(fn) {
    this.handler = fn
  }
  notify(method, params) {
    state.notifications.push({ method, params })
  }
  start() {}
  flush() {}
  close() {}
}

export const fakeChild = {
  stdio: [null, null, null, {}, {}],
  on() {},
  kill() {},
}
